1681	/****************************************************************************
1682	 * Private Data — Operations Structure
1683	 ****************************************************************************/
1684	
1685	static const struct netdev_ops_s g_ops =
1686	{
1687	  netdriver_ifup,      /* ifup */
1688	  netdriver_ifdown,    /* ifdown */
1689	  netdriver_transmit,  /* transmit */
1690	  netdriver_receive    /* receive */
1691	};
